mapper.select:
SELECT p.id, p.real_name, p.id_card, p.birthday, p.nation, p.address, p.native_place, p.gender, p.marital_status, p.education, p.person_code, p.photo, p.mobile, p.emergency_contact, p.emergency_phone, p.email, p.entry_date, p.leave_date, p.person_type, p.order_no, p.status, p.del_flag, p.create_by, p.create_time, p.update_by, p.update_time FROM md_person p WHERE p.del_flag = 1
AND p.real_name LIKE #{realName}
AND p.mobile LIKE #{mobile}
AND p.person_code LIKE #{personCode}
ORDER BY p.create_time DESC
